INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('fashion-studio', 'הסטודיו הדיגיטלי למעצבת האופנה', '67 עמודי תכנון ושרטוט למעצבות אופנה — קרוקי מקצועיים, סקיצות שטוחות, תיק טכני ולוחות השראה. תואם GoodNotes ו-Procreate.', 'ערכה דיגיטלית מקצועית ומקיפה למעצבות אופנה, סטודנטיות לעיצוב וכל מי שחולמת להיכנס לתחום. 67 עמודים שמלווים אותך משלב ההשראה ועד הקולקציה המוגמרת: תבניות קרוקי מקצועיות, דפי סקיצה שטוחה, תיקי מוצר טכניים, לוחות מצב רוח ופלטות צבע מוכנות. נפתח על טאבלט או מחשב, מתאים ל-GoodNotes, Procreate, Notability — או להדפסה.', '["תבניות קרוקי מקצועיות (חזית, גב ופרופיל)", "דפי סקיצה שטוחה — flat sketch", "תיקי מוצר טכניים (tech pack) מוכנים למילוי", "לוחות מצב רוח ופלטות צבע עם קודי צבע", "דפי תכנון קולקציה ותרגול סקיצה", "תואם GoodNotes / Procreate / הדפסה · הורדה מיידית"]', 129, 169, 'fashion', 'חדש', 'rose', 5, 0, '/static/img/product-fashion-studio.jpg', '', '', '', '', 'https://paypal.me/ecocraftdigital/129', NULL, 0);
INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('adhd-planner', 'מתכנן ADHD דיגיטלי', 'מתכנן ממוקד לבעלי הפרעת קשב — פירוק משימות, מיקוד וניהול יום בעברית.', 'מתכנן דיגיטלי שנבנה במיוחד למוח נוירו-שונה. עם מבנה ברור ופשוט לפירוק משימות גדולות לצעדים קטנים, מעקב מיקוד יומי, ותכנון שבועי שלא מציף. מתאים ל-GoodNotes, Notability וכל אפליקציית PDF.', '["קובץ PDF היפר-קישורי (מעל 40 עמודים)", "תואם GoodNotes / Notability / Xodo", "פירוק משימות + מעקב הרגלים", "תכנון יומי, שבועי וחודשי", "הורדה מיידית לאחר הרכישה"]', 39, 59, 'planners', 'הכי נמכר', 'rose', 5, 0, '/static/img/product-adhd-planner.jpg', '', '', '', '', '', NULL, 1);
INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('kids-bundle', 'חבילת 5 משחקים אינטראקטיביים', '5 משחקי למידה אינטראקטיביים לילדים — בלי הדפסה, עובד על כל מכשיר.', 'חבילה של חמישה משחקי למידה אינטראקטיביים לילדים בגילאי 5–12: לוח הכפל, ערבוב מילים, קריאת שעון, חידון גיאוגרפיה ו-Math Blitz. עובד ישירות בדפדפן — בלי אפליקציה, בלי הדפסה, בעברית ובאנגלית.', '["5 משחקים אינטראקטיביים בקובץ אחד", "עובד על טאבלט, מחשב וטלפון", "עברית ואנגלית", "מצב טיימר וכוכבי תגמול", "גילאי 5–12 · הורדה מיידית"]', 49, 95, 'games', 'חבילה משתלמת', 'sage', 5, 0, '/static/img/product-kids-bundle.jpg', '', '', '', '', '', NULL, 2);
INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('ai-course', 'קורס AI לנשות עסקים', 'ללמוד לרתום בינה מלאכותית לעסק — צעד אחר צעד, בעברית פשוטה.', 'קורס דיגיטלי מעשי לנשות עסקים שרוצות לרתום כלי בינה מלאכותית לעסק שלהן — כתיבת תוכן, שיווק, עיצוב ואוטומציות. שיעורים קצרים, תרגילים ותבניות מוכנות. ללא ידע טכני מוקדם.', '["12 שיעורי וידאו קצרים", "תבניות פרומפטים מוכנות", "תרגילים מעשיים לכל שיעור", "גישה לכל החיים + עדכונים", "בעברית, ללא רקע טכני"]', 89, 149, 'courses', 'חדש', 'rose', 5, 0, '', 'קורס AI לנשות עסקים', 'EcoCraft Digital', '#6E8767', '#4F634A', 'https://paypal.me/ecocraftdigital/89', NULL, 3);
INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('focus-planner', 'מתכנן פוקוס יומי — FocusMate', 'מתכנן יומי מינימליסטי שמחבר בין זרימה, מיקוד ורעיונות.', 'מתכנן יומי אלגנטי שמאזן בין תכנון משימות למרחב לרעיונות. עם בלוק מיקוד יומי, מקום ל-3 מטרות עיקריות ותיבת מחשבות. עיצוב נקי בגווני המותג, תואם GoodNotes.', '["מתכנן יומי + שבועי", "בלוק מיקוד ו-3 מטרות", "תיבת רעיונות ומחשבות", "תואם GoodNotes / PDF", "הורדה מיידית"]', 59, NULL, 'planners', '', 'rose', 5, 0, '', 'FocusMate', 'Where Flow &amp; Ideas Meet', '#C98B8B', '#A96A6A', '', NULL, 4);
INSERT OR IGNORE INTO products (slug, name, short_description, description, includes, price, old_price, category_id, tag, tag_type, rating, reviews, image_url, cover_title, cover_sub, cover_from, cover_to, paypal_url, file_id, sort_order) VALUES ('morning-focus', 'בוקר פוקוס — ערכת הבוקר הממוקד', 'ערכת בוקר אינטראקטיבית לנוירו-שונים — מצב רוח, אנרגיה, טעינת גוף ומשימה אחת עם טיימר.', 'כלי בוקר עדין ואינטראקטיבי שנבנה למוח מוסט אבל לב ממוקד. בוחרים מצב רוח ורמת אנרגיה, מסמנים ''טעינת גוף'' (מים, נשימות, תנועה ואור), וכותבים את המשימה האחת של היום — עם פוקוס טיימר של 25 דקות. נפתח בכל דפדפן, במחשב או בטלפון, והנתונים נשמרים אוטומטית.', '["קובץ HTML אינטראקטיבי — נפתח בכל דפדפן", "מעקב מצב רוח ורמת אנרגיה", "צ''ק-ליסט ''טעינת גוף'' לבוקר", "משימה אחת + פוקוס טיימר 25 דקות", "שמירה אוטומטית בדפדפן", "עברית מלאה · הוראות שימוש מצורפות"]', 69, NULL, 'planners', 'חדש', 'rose', 5, 0, '', 'בוקר פוקוס', 'ערכת הבוקר הממוקד', '#ce4578', '#a8305f', '', 'morning-focus-file', 5);

INSERT OR IGNORE INTO site_settings (key, value) VALUES ('design', '{"brandName": "EcoCraft Digital", "brandSub": "ELEGANT DIGITAL CREATIONS", "logoText": "ED", "currency": "₪", "colors": {"sage": "#6E8767", "sageDeep": "#4F634A", "rose": "#C98B8B", "cream": "#F6F3EC", "ink": "#3A382F"}, "headingFont": "Frank Ruhl Libre", "heroStyle": "side", "homeSections": [{"id": "featured", "on": true}, {"id": "features", "on": true}, {"id": "about", "on": true}], "heroEyebrow": "מוצרים דיגיטליים בעברית", "heroTitle": "יצירות דיגיטליות עדינות, לחיים מסודרים יותר", "heroSubtitle": "Elegant digital creations", "heroLead": "מתכננים, משחקי למידה וקורסים דיגיטליים — מעוצבים באהבה, מותאמים לישראל, ומגיעים אלייך מיד עם הרכישה.", "heroImg": "/static/img/hero.jpg", "aboutImg": "/static/img/about.jpg", "heroBadge": "", "heroBadgeSub": "", "featuredTitle": "מוצרים אהובים במיוחד", "featuredSub": "מבחר המוצרים שלנו — מוכנים לשימוש מיד.", "trust": ["הורדה מיידית", "מחירים בשקלים", "תואם GoodNotes", "עברית מלאה"], "features": [{"icon": "bolt", "title": "הורדה מיידית", "body": "הקובץ מגיע לתיבת המייל שלך שניות אחרי הרכישה — בלי המתנה."}, {"icon": "heart", "title": "נוצר באהבה", "body": "כל מוצר מעוצב בקפידה בגווני המותג, עם תשומת לב לכל פרט."}, {"icon": "globe", "title": "מותאם לישראל", "body": "עברית מלאה, כיווניות RTL ומחירים בשקלים — בלי הפתעות."}], "aboutTitle": "כלים דיגיטליים שעוזרים לחיות בנחת", "aboutText": "EcoCraft Digital נולד מתוך אהבה לסדר, לעיצוב עדין ולכלים שבאמת עוזרים. אנחנו יוצרות מתכננים, משחקי למידה וקורסים שמתאימים לקצב החיים הישראלי — פשוטים, יפים ונגישים.\nכל מוצר הוא דיגיטלי לחלוטין: קונים, מורידים ומתחילים להשתמש — בלי משלוח ובלי המתנה.", "footerTagline": "מתכננים, משחקים וקורסים דיגיטליים — מעוצבים באהבה, מותאמים לישראל.", "featuredIds": ["adhd-planner", "ai-course"], "contactEmail": "ecocraftdigital@gmail.com", "contactPhone": "0507148144"}');
